        }
        List<Claim> numbered = kept.stream().filter(c -> c.getNumber() != null)
                .sorted(Comparator.comparing((Claim c) -> openedOn.get(c.getId()))
                        .thenComparing(c -> claimIds.get(c.getId())))
                .toList();
        Map<String, String> renumbered = new HashMap<>();
